async function adjustCoins(env, userId, amount, reason, shortId = null) {
  await env.DB.batch([
    env.DB.prepare("UPDATE users SET coins = coins + ? WHERE id = ?").bind(amount, userId),
    env.DB.prepare("INSERT INTO coin_transactions (user_id, amount, reason, short_id) VALUES (?, ?, ?, ?)").bind(userId, amount, reason, shortId),
  ]);
}

// ---------------------------------------------------------------------------
// #CoinStore helpers — paid / free mode, default price, daily check-in rules
// ---------------------------------------------------------------------------
let coinSchemaReady = false;
async function ensureCoinSchema(env) {
  if (coinSchemaReady) return;
  const stmts = [
    "ALTER TABLE site_settings ADD COLUMN paid_mode INTEGER DEFAULT 1",
    "ALTER TABLE site_settings ADD COLUMN default_coin_cost INTEGER DEFAULT 2",
    "ALTER TABLE site_settings ADD COLUMN force_daily_checkin INTEGER DEFAULT 1",
    "ALTER TABLE site_settings ADD COLUMN checkin_streak_bonus INTEGER DEFAULT 5",
    "ALTER TABLE files ADD COLUMN coin_cost INTEGER DEFAULT 0",
    // #UsernamePolicy
    "ALTER TABLE site_settings ADD COLUMN username_change_cost INTEGER DEFAULT 50",
    "ALTER TABLE site_settings ADD COLUMN username_change_cooldown_days INTEGER DEFAULT 720",
    "ALTER TABLE users ADD COLUMN username_admin_lock INTEGER DEFAULT 0",
    "ALTER TABLE users ADD COLUMN username_changed_at INTEGER",
    // #UserCountry: locked at first sight from the IP (never user-editable) + the user's own Tamil/English choice.
    "ALTER TABLE users ADD COLUMN country TEXT",
    "ALTER TABLE users ADD COLUMN lang_pref TEXT",
  ];
  for (const sql of stmts) {
    try { await env.DB.prepare(sql).run(); }
    catch (e) {
      if (!/duplicate column|already exists/i.test(String(e && e.message))) console.error("ensureCoinSchema:", e);
    }
  }
  coinSchemaReady = true;
}

function coinConfigFrom(s = {}) {
  const num = (v, d) => (v === null || v === undefined || v === "" || !Number.isFinite(Number(v)) ? d : Number(v));
  return {
    paidMode: num(s.paid_mode, 1) !== 0,
    defaultCost: Math.max(0, Math.trunc(num(s.default_coin_cost, 2))),
    forceCheckin: num(s.force_daily_checkin, 1) !== 0,
    checkinCoins: Math.max(0, Math.trunc(num(s.checkin_coins, 10))),
    streakBonus: Math.max(0, Math.trunc(num(s.checkin_streak_bonus, 5))),
    // #UsernamePolicy: coins charged per username change, and how many days the name stays locked afterwards.
    usernameChangeCost: Math.max(0, Math.trunc(num(s.username_change_cost, 50))),
    usernameCooldownDays: Math.max(0, Math.trunc(num(s.username_change_cooldown_days, 720))),
  };
}

// #UsernamePolicy helpers ----------------------------------------------------
const USERNAME_RE = /^[a-zA-Z0-9_]{2,24}$/;
// Names nobody may take (stops people impersonating the site / staff).
const RESERVED_USERNAMES = new Set([
  "admin", "administrator", "root", "support", "staff", "moderator", "mod", "owner",
  "system", "official", "glitz", "glitzscreen", "help", "security", "null", "undefined",
]);
function isReservedUsername(name) {
  return RESERVED_USERNAMES.has(String(name || "").toLowerCase());
}
// Returns { locked, unlockAt, daysLeft } for a user row. A user whose name was never
// set/changed through the site (legacy accounts, username_changed_at = NULL) is not locked.
function usernameLockState(user, cfg) {
  const days = cfg && Number.isFinite(cfg.usernameCooldownDays) ? cfg.usernameCooldownDays : 720;
  // #UsernameAdminLock: the admin can lock a name until the admin unlocks it (no countdown).
  if (user && Number(user.username_admin_lock) === 1) return { locked: true, adminLocked: true, unlockAt: 0, daysLeft: 0 };
  const base = Number(user && user.username_changed_at) || 0;
  if (!base || days <= 0) return { locked: false, unlockAt: 0, daysLeft: 0 };
  const unlockAt = base + days * 86400;
  const now = Math.floor(Date.now() / 1000);
  if (now >= unlockAt) return { locked: false, unlockAt, daysLeft: 0 };
  return { locked: true, unlockAt, daysLeft: Math.ceil((unlockAt - now) / 86400) };
}
function formatJoinDate(ts) {
  const n = Number(ts);
  if (!Number.isFinite(n) || n <= 0) return "—";
  return new Date(n * 1000).toLocaleDateString("en-GB", { timeZone: "UTC", day: "numeric", month: "long", year: "numeric" });
}

// What a viewer actually pays right now: 0 in free mode, else the video's own price.
function effectiveCoinCost(video, coin) {
  if (!coin || !coin.paidMode) return 0;
  const c = Number(video && video.coin_cost);
  return Number.isFinite(c) && c > 0 ? Math.trunc(c) : 0;
}

function parseCoinCostInput(raw, fallback) {
  if (raw === undefined || raw === null || String(raw).trim() === "") return fallback;
  const n = Number(raw);
  if (!Number.isFinite(n) || n < 0) return fallback;
  return Math.min(100000, Math.trunc(n));
}

// Thumbnail overlay: Claimed > Free > coin cost.
function coinBadgeHtml(video, coin, unlockedSet) {
  if (unlockedSet && unlockedSet.has(video.short_id)) return `<span class="coin-overlay claimed">✅ Claimed</span>`;
  const cost = effectiveCoinCost(video, coin);
  if (cost <= 0) return `<span class="coin-overlay free">FREE</span>`;
  return `<span class="coin-overlay paid">🪙 ${cost}</span>`;
}

// #QualityTag: HD / CAM badge shown on every thumbnail, colored via the
// --hd-color / --cam-color CSS variables (theme accent by default for HD,
// red by default for CAM — both admin-editable in Admin > Site theme).
function qualityBadgeHtml(video) {
  const tag = normalizeQualityTag(video && video.quality_tag);
  return `<span class="quality-badge quality-${tag.toLowerCase()}">${tag}</span>`;
}

// Shared "home screen" movie card — used by the main gallery grid AND the
// "You might also like" shelf on the watch page, so both look identical.
function videoCardHtml(v, coinCfg, unlockedSet) {
  const duration = formatDuration(v.duration_seconds);
  const avgRating = Number(v.avg_rating || 0);
  const ratingCount = Number(v.rating_count || 0);
  return `
      <a class="card" href="/watch?id=${encodeURIComponent(v.short_id)}"
         data-provider="${escapeHtml(v.provider || 'facebook')}"
         data-short-id="${escapeHtml(v.short_id)}">
        <div class="thumb-wrap">
          <img src="${escapeHtml(v.thumbnail_url || "")}" alt="${escapeHtml(v.file_name || "")}" loading="lazy" onerror="this.style.opacity=0">
          ${qualityBadgeHtml(v)}
          ${coinBadgeHtml(v, coinCfg, unlockedSet)}
          ${duration ? `<span class="duration-badge">${duration}</span>` : ""}
        </div>
        <div class="body">
          <div class="title">${escapeHtml(v.file_name || "Untitled")}${v.release_year ? ` (${v.release_year})` : ""}</div>
          <div class="meta">
            <span class="meta-item"><span class="meta-icon">👁</span>${formatCount(v.views)}</span>
            <span class="meta-item ${v.likes > 0 ? "has-likes" : ""}"><span class="meta-icon">❤️</span>${formatCount(v.likes)}</span>
            <span class="meta-item"><span class="meta-icon">💔</span>${formatCount(v.dislikes)}</span>
          </div>
          <div class="card-rating ${ratingCount > 0 ? "" : "muted"}">
            ${
              ratingCount > 0
                ? `<span class="card-rating-stars">${starString(avgRating)}</span> ${avgRating.toFixed(1)} <span class="muted">(${formatCount(ratingCount)})</span>`
                : `⭐ No ratings yet`
            }
          </div>
        </div>
      </a>`;
}

// Consecutive-day check-in streak (UTC days). Counts back from today if it is
// already claimed, otherwise from yesterday.
async function getCheckinStreak(env, userId, today) {
  const { results } = await env.DB.prepare(
    "SELECT checkin_date FROM daily_checkins WHERE user_id = ? ORDER BY checkin_date DESC LIMIT 60"
  ).bind(userId).all();
  const dates = new Set((results || []).map((r) => r.checkin_date));
  const d = new Date(today + "T00:00:00Z");
  if (!dates.has(today)) d.setUTCDate(d.getUTCDate() - 1);
  let streak = 0;
  while (dates.has(d.toISOString().slice(0, 10))) {
    streak++;
    d.setUTCDate(d.getUTCDate() - 1);
  }
  return streak;
}

async function getSiteSettings(env) {
  const _cachedSettings = perfCacheGet("siteSettings");
  if (_cachedSettings) return _cachedSettings;
  await ensureCoinSchema(env);
  await ensureQualityTagSchema(env); // #QualityTag
  const row = await env.DB.prepare(
    `SELECT free_signup_coins, max_signups_per_ip_per_day, checkin_coins,
            paid_mode, default_coin_cost, force_daily_checkin, checkin_streak_bonus,
            username_change_cost, username_change_cooldown_days,
            theme_bg, theme_surface, theme_primary, theme_secondary, theme_text, theme_accent, theme_radius_px, active_theme_name,
            quality_hd_color, quality_cam_color
       FROM site_settings WHERE id = 1`
  ).first();
  return perfCacheSet("siteSettings", row || { free_signup_coins: 0, max_signups_per_ip_per_day: 5, checkin_coins: 10 }, 180000);
}

// ---------------------------------------------------------------------------
// Centralized KV service — ON / OFF / AUTO modes with independent
// per-operation (read/write/delete/list) fallback to D1.
//
// D1 remains the source of truth everywhere; KV (the VIDEO_LIST_CACHE
// namespace) is only ever an optional cache layer. This module is the ONLY
// place that touches env.VIDEO_LIST_CACHE directly — every other function
// in the file goes through kvGet/kvPut/kvDelete/kvList so mode/threshold/
// fallback/error-handling is applied uniformly, in one place.
//
// Usage tracking is D1-based (see kv_usage table) specifically because
// tracking KV usage via another KV call would spend the very quota it's
// trying to measure. Each actual KV call fires a single, non-blocking
// (ctx.waitUntil) UPSERT — it never blocks or slows down the response, and
// it's the only D1 write this system adds per KV operation.
// ---------------------------------------------------------------------------

const KV_DAILY_LIMITS = { read: 100000, write: 1000, delete: 1000, list: 1000 };

function utcDayString() {
  return new Date().toISOString().slice(0, 10);
}

// ---- #PerfCache: tiny per-isolate caches that save D1 rows read ----------------
// Admin writes (POST /api/admin/...) bypass and clear every cache so the admin
// always sees fresh data; other isolates pick the change up within the TTL.
const _perfCache = new Map();
let _perfCacheBypass = 0;
function perfCacheGet(key) {
  if (_perfCacheBypass > 0) return undefined;
  const hit = _perfCache.get(key);
  if (hit && hit.exp > Date.now()) return hit.value;
  if (hit) _perfCache.delete(key);
  return undefined;
}
function perfCacheSet(key, value, ttlMs) {
  if (_perfCacheBypass > 0) return value;
  if (_perfCache.size >= 200) _perfCache.delete(_perfCache.keys().next().value);
  _perfCache.set(key, { value, exp: Date.now() + ttlMs });
  return value;
}
function perfCacheClear() {
  _perfCache.clear();
  _langCfgCache = null;
  _catLangCache = null;
}

async function getKvSettings(env) {
  const cached = perfCacheGet("kvSettings");
  if (cached) return cached;
  const row = await env.DB.prepare("SELECT kv_mode, kv_threshold_percent FROM site_settings WHERE id = 1").first();
  const mode = row && ["on", "off", "auto"].includes(row.kv_mode) ? row.kv_mode : "auto";
  const thresholdPercent = row && row.kv_threshold_percent ? Number(row.kv_threshold_percent) : 90;
  return perfCacheSet("kvSettings", { mode, thresholdPercent }, 300000);
}

async function getKvUsageToday(env) {
  const day = utcDayString();
  const { results } = await env.DB.prepare("SELECT operation, count FROM kv_usage WHERE day = ?").bind(day).all();
  const usage = { read: 0, write: 0, delete: 0, list: 0 };
  for (const r of results || []) usage[r.operation] = r.count;
  return { day, usage };
}

// Builds a per-request KV context: reads mode + today's usage ONCE (two
// lightweight D1 reads, skipped entirely in OFF mode since KV is never
// touched), then every kvGet/kvPut/kvDelete/kvList call in that same
// request reuses this single decision instead of re-querying.
async function createKvContext(request, env, ctx) {
  const settings = await getKvSettings(env);

  if (settings.mode === "off") {
    return { env, ctx, mode: "off", settings, fallback: { read: true, write: true, delete: true, list: true }, usage: null };
  }
  if (settings.mode === "on") {
    return { env, ctx, mode: "on", settings, fallback: { read: false, write: false, delete: false, list: false }, usage: null };
  }

  // Usage counters were removed: AUTO behaves like ON (a failing KV call still falls back to D1 per request).
  return { env, ctx, mode: "on", settings, fallback: { read: false, write: false, delete: false, list: false }, usage: null };
}

// Fire-and-forget usage increment — never awaited by the caller, never
// blocks the response, and is the ONLY write this system performs per KV
// call (one UPSERT, not a read-then-write).
function trackKvUsage(kvCtx, operation) {
  if (!kvCtx || kvCtx.mode === "off" || !_trackFlags.kvLive) return; // OFF mode never touches KV; KV live status OFF = no counting
  const day = utcDayString();
  const promise = kvCtx.env.DB.prepare(
    "INSERT INTO kv_usage (operation, day, count) VALUES (?, ?, 1) ON CONFLICT(operation, day) DO UPDATE SET count = count + 1"
  )
    .bind(operation, day)
    .run()
    .catch((err) => console.error("kv_usage tracking failed (non-fatal)", err));
  if (kvCtx.ctx && kvCtx.ctx.waitUntil) kvCtx.ctx.waitUntil(promise);
}

async function kvGet(kvCtx, key, type) {
  if (!kvCtx || kvCtx.mode === "off" || kvCtx.fallback.read) return null;
  try {
    const result = await kvCtx.env.VIDEO_LIST_CACHE.get(key, type);
    trackKvUsage(kvCtx, "read");
    return result;
  } catch (err) {
    console.error("KV read failed — falling back to D1/origin for this request", err);
    kvCtx.fallback.read = true; // this request only; AUTO mode re-evaluates fresh next request
    return null;
  }
}

async function kvPut(kvCtx, key, value, opts) {
  if (!kvCtx || kvCtx.mode === "off" || kvCtx.fallback.write) return false;
  try {
    await kvCtx.env.VIDEO_LIST_CACHE.put(key, value, opts);
    trackKvUsage(kvCtx, "write");
    return true;
  } catch (err) {
    console.error("KV write failed — D1 already holds the authoritative data, cache update skipped", err);
    kvCtx.fallback.write = true;
    return false;
  }
}

async function kvDelete(kvCtx, key) {
  if (!kvCtx || kvCtx.mode === "off" || kvCtx.fallback.delete) return false;
  try {
    await kvCtx.env.VIDEO_LIST_CACHE.delete(key);
    trackKvUsage(kvCtx, "delete");
    return true;
  } catch (err) {
    console.error("KV delete failed — stale cache entry may persist until its TTL expires", err);
    kvCtx.fallback.delete = true;
    return false;
  }
}

async function kvList(kvCtx, opts) {
  if (!kvCtx || kvCtx.mode === "off" || kvCtx.fallback.list) return null;
  try {
    const result = await kvCtx.env.VIDEO_LIST_CACHE.list(opts);
    trackKvUsage(kvCtx, "list");
    return result;
  } catch (err) {
    console.error("KV list failed — falling back to D1/origin for this request", err);
    kvCtx.fallback.list = true;
    return null;
  }
}

// ---------------------------------------------------------------------------
// Edge / CDN cache (#EdgeCache)
//
// A thin layer on top of `caches.default` — the same Cache API Cloudflare's
// own CDN uses for static assets — for public, non-personalized JSON GET
// endpoints. This sits IN FRONT OF the KV cache above: a hit here means the
// request never reaches this Worker's JS at all on repeat visits from
// nearby, so it's strictly less work than a KV hit (which still runs a
// Worker invocation), and it's shared across every colo Cloudflare has
// edge-cached the response to, not just one KV read.
//
// Only ever wrap routes whose response is identical for every visitor
// (search/category/sort results, a single video's public stats, the
// category list, comments, player settings). Never wrap anything that
// depends on the caller's session (likes state, coins, /api/me, admin,
// playlists, watch history) — caches.default has no concept of "per user",
// so doing that would leak one visitor's data to the next.
// ---------------------------------------------------------------------------
async function withEdgeCache(request, ctx, ttlSeconds, handler) {
  // Only GET is cacheable, and only when the Cache API is actually present
  // in this runtime (it is on real Cloudflare Workers; some local/test
  // harnesses omit it — fail open to the normal handler rather than throw).
  if (request.method !== "GET" || typeof caches === "undefined" || !caches.default) {
    return handler();
  }
  const cache = caches.default;
  // Cloudflare keys the edge cache by request URL (query string included),
  // which is exactly the variation these endpoints have (q/category/sort/id).
  const cacheKey = new Request(new URL(request.url).toString(), request);

  const hit = await cache.match(cacheKey);
  if (hit) return hit;

  const response = await handler();
  if (response.status === 200) {
    const cacheable = new Response(response.body, response);
    cacheable.headers.set("cache-control", `public, max-age=${ttlSeconds}`);
    // Store without blocking the response the visitor is waiting on.
    ctx.waitUntil(cache.put(cacheKey, cacheable.clone()));
    return cacheable;
  }
  return response;
}

// Admin-facing KV settings snapshot. Quota counters were removed, so this only
// reports the saved mode / threshold (the Settings panel needs nothing else).
async function getKvStatus(env) {
  const settings = await getKvSettings(env);
  return {
    mode: settings.mode,
    thresholdPercent: settings.thresholdPercent,
    overallStatus: settings.mode === "off" ? "OFF" : "ACTIVE",
    estimated: true,
    nextResetUtc: null,
    operations: {},
  };
}


// ---------------------------------------------------------------------------
// #KvBrowser — admin-only helpers that let the KV System panel show the
// VIDEO_LIST_CACHE namespace like a D1 table: one row per key with a value
// preview, size and expiry, plus view / delete. These are explicit admin
// actions, so they bypass the ON/OFF/AUTO fallback (an admin can still
// inspect the namespace while the site itself is in OFF mode), but they
// ARE counted in the same kv_usage counters so "Live status" stays honest.
// ---------------------------------------------------------------------------
const KV_BROWSER_VALUE_CAP = 256 * 1024; // bytes shown in the value viewer

function kvBrowserBinding(env) {
  if (!env.VIDEO_LIST_CACHE) throw new Error("VIDEO_LIST_CACHE KV binding is not configured in wrangler.toml");
  return env.VIDEO_LIST_CACHE;
}

// Adds `n` to today's counter for one operation with a single UPSERT.
function trackKvUsageN(env, ctx, operation, n) {
  if (!n || !_trackFlags.kvLive) return;
  const promise = env.DB.prepare(
    "INSERT INTO kv_usage (operation, day, count) VALUES (?, ?, ?) ON CONFLICT(operation, day) DO UPDATE SET count = count + excluded.count"
  )
    .bind(operation, utcDayString(), n)
    .run()
    .catch((err) => console.error("kv_usage tracking failed (non-fatal)", err));
  if (ctx && ctx.waitUntil) ctx.waitUntil(promise);
}

function kvLooksLikeJson(text) {
  const t = String(text || "").trim();
  if (!t || (t[0] !== "{" && t[0] !== "[")) return false;
  try { JSON.parse(t); return true; } catch { return false; }
}

async function kvBrowserList(env, ctx, { prefix = "", cursor = "", limit = 25, withValues = true } = {}) {
  const kv = kvBrowserBinding(env);
  const opts = { limit: Math.max(1, Math.min(50, Math.trunc(Number(limit)) || 25)) };
  if (prefix) opts.prefix = String(prefix).slice(0, 200);
  if (cursor) opts.cursor = String(cursor);
  const res = await kv.list(opts);
  trackKvUsageN(env, ctx, "list", 1);

  let reads = 0;
  const keys = await Promise.all(
    (res.keys || []).map(async (k) => {
      const row = { name: k.name, expiration: k.expiration || null, metadata: k.metadata || null, size: null, preview: "", isJson: false };
      if (!withValues) return row;
      try {
        const text = await kv.get(k.name, "text");
        reads++;
        if (text !== null && text !== undefined) {
          row.size = new TextEncoder().encode(text).length;
          row.preview = text.length > 140 ? text.slice(0, 140) + "…" : text;
          row.isJson = kvLooksLikeJson(text);
        }
      } catch (err) {
        row.preview = "(read failed: " + String(err && err.message ? err.message : err) + ")";
      }
      return row;
    })
  );
  trackKvUsageN(env, ctx, "read", reads);
  return { keys, cursor: res.list_complete ? null : res.cursor || null, listComplete: !!res.list_complete };
}

async function kvBrowserGet(env, ctx, key) {
  const kv = kvBrowserBinding(env);
  const { value, metadata } = await kv.getWithMetadata(key, "text");
  trackKvUsageN(env, ctx, "read", 1);
  if (value === null || value === undefined) return null;
  const size = new TextEncoder().encode(value).length;
  const isJson = kvLooksLikeJson(value);
  let shown = value;
  let truncated = false;
  if (size > KV_BROWSER_VALUE_CAP) { shown = value.slice(0, KV_BROWSER_VALUE_CAP); truncated = true; }
  else if (isJson) { try { shown = JSON.stringify(JSON.parse(value), null, 2); } catch { /* keep raw */ } }
  // Expiration comes from list(); a single-key lookup is cheaper and good enough here.
  let expiration = null;
  try {
    const listed = await kv.list({ prefix: key, limit: 1 });
    trackKvUsageN(env, ctx, "list", 1);
    const hit = (listed.keys || []).find((k) => k.name === key);
    expiration = hit ? hit.expiration || null : null;
  } catch { /* expiry is informational only */ }
  return { key, value: shown, size, isJson, truncated, expiration, metadata: metadata || null };
}

async function kvBrowserDelete(env, ctx, key) {
  const kv = kvBrowserBinding(env);
  await kv.delete(key);
  trackKvUsageN(env, ctx, "delete", 1);
}


// ---------------------------------------------------------------------------
// D1 / KV usage counters were REMOVED (they cost extra D1 reads + writes on every
// request). These tiny stubs keep the old call sites harmless.
// ---------------------------------------------------------------------------
function d1Raw(db) { return db; }
function d1TrackEnv(env) { return env; }
function d1MaybeFlush() { /* removed */ }
function d1FlushUsage() { return Promise.resolve(); }

