async function withAdminChrome(request, env, response) {
  try {
    if (!response || request.method !== "GET") return response;
    const ct = response.headers.get("content-type") || "";
    if (!ct.includes("text/html")) return response;
    if (!(await isAdminRequest(request, env))) return response;
    let text = await response.text();
    // #AdminFree: tell the page (before any other script runs) that this is a verified admin, so the visitor-only protection stays off.
    {
      const adminFlagHead = "<script>window.__tzAdmin=1;</script>";
      const headMatch = text.match(/<head[^>]*>/i);
      if (headMatch) {
        const at = headMatch.index + headMatch[0].length;
        text = text.slice(0, at) + adminFlagHead + text.slice(at);
      } else {
        text = adminFlagHead + text;
      }
    }
    const chip =
      `<a class="user-chip" href="/admin" title="You are logged in as admin">🛡️ Admin</a>` +
      `<a href="#" class="link-muted" onclick="event.preventDefault();fetch('/api/admin/logout',{method:'POST'}).finally(function(){location.href='/';});">Admin logout</a>`;
    text = text.replace(/<!--GUEST_AUTH_START-->[\s\S]*?<!--GUEST_AUTH_END-->/, "");
    text = text.replace("<!--ADMIN_NAV-->", chip);
    // #AdminMobileNav: the mobile bottom bar showed "Log in" (and no Claimed
    // tab) for the admin. Swap Log in -> Admin and add a Claimed tab, on
    // desktop and mobile, only when the page doesn't already have one.
    const adminActive = /\/admin(\/|$)/.test(new URL(request.url).pathname);
    text = text.replace(/<a href="\/login"([^>]*)><span class="ic">👤<\/span>Log in<\/a>/,
      `<a href="/admin" class="${adminActive ? "active" : ""}"><span class="ic">🛡️</span>Admin</a>`);
    text = text.replace(/(<nav class="bottom-nav"[^>]*>(?:(?!<\/nav>)[\s\S])*?)(<a href="\/\?focus=search")/, (m, a, b) =>
      a.includes("claimed=1") ? m : `${a}<a href="/?claimed=1"><span class="ic">✅</span>Claimed</a>\n    ${b}`);
    text = text.replace(/(<nav class="desktop-nav"[^>]*>(?:(?!<\/nav>)[\s\S])*?)(<\/nav>)/, (m, a, b) =>
      a.includes("claimed=1") ? m : `${a}<a href="/?claimed=1">✅ Claimed</a>${b}`);
    // #AdminDeviceFlag: remember on THIS browser that it belongs to the admin, so
    // the presence/view scripts stay silent even if the cookies expire or get cleared.
    const flagScript = `<script>try{localStorage.setItem("tz_admin_dev","1")}catch(e){}</script>`;
    const bodyEnd = text.lastIndexOf("</body>");
    text = bodyEnd === -1 ? text + flagScript : text.slice(0, bodyEnd) + flagScript + text.slice(bodyEnd);
    const headers = new Headers(response.headers);
    headers.delete("content-length");
    headers.set("cache-control", "private, no-store");
    // Sliding renewal so the admin cookie never expires while they're using the site.
    try {
      const renewed = await signAdminToken(env, Date.now() + ADMIN_SESSION_TTL_SECONDS * 1000);
      headers.append("set-cookie", setCookieHeader(ADMIN_SESSION_COOKIE, renewed, ADMIN_SESSION_TTL_SECONDS));
      headers.append("set-cookie", setCookieHeader(ADMIN_DEVICE_COOKIE, await signDeviceToken(env), ADMIN_DEVICE_TTL_SECONDS));
    } catch (e) { /* keep the old cookie */ }
    return new Response(text, { status: response.status, statusText: response.statusText, headers });
  } catch (err) {
    console.error("withAdminChrome failed:", err);
    return response;
  }
}

