    add += '<script type="speculationrules">' + FUTURE_SPEC_RULES + "</script>";
    add += '<style id="fbf-pre-css">' + FUTURE_PRE_CSS + "</style>";

    const admin = await isAdminRequest(request, env);
    const cfg = { admin: !!admin, shield: FUTURE_SHIELD_MODE, adsense: /googlesyndication\.com/.test(text) };
    const headHtml = '<script id="fbf-head">' + FUTURE_HEAD_JS + "</script>";
    const bootHtml = '<script id="fbf-boot">window.__FBF_CFG=' + JSON.stringify(cfg).replace(/</g, "\\u003c") + ";" + FUTURE_BOOT_JS + "</script>";

    const cs = text.match(/<meta charset=[^>]*>/i);
